package main
import "fmt"
func main() {
	// 请勿更改该数组
    results := []string{"w", "l", "w", "d", "w", "l", "l", "l", "d", "d", "w", "l", "w", "d"}
    var s string
    fmt.Scanln(&s)
    var sum int
    switch s {
    	case "w":
    	sum = 3
    	case "d":
    	sum = 1
    }
    for _,x := range results{
    	if x =="w"{
    		sum += 3
    	}
    	if x == "d"{
    		sum += 1
    	}
    }
    fmt.Println(sum)
}
